const body = ($json.body && $json.body) || $json;
const s = (v) => (v !== undefined && v !== null) ? String(v).trim() : '';
const image_url = s(body.image_url);
const product_video_id = s(body.product_video_id);
const video_url = s(body.video_url);
const isHttp = (u) => /^https?:\/\//.test(u);
// Реальный контракт Creatify (сверено 13.08): gen_image принимает product_url (прямой URL изображения),
// gen_video принимает {id} задачи в path (НЕ URL видео). video_url как вход не поддерживается.
if (video_url && !image_url && !product_video_id) {
  return [{ json: { ok: false, error: "video_url не поддерживается реальным контрактом Creatify product_to_videos: gen_video принимает id задачи (product_video_id), а не URL видео. Передайте image_url (1 кред, создаёт задачу) или product_video_id (3 кред, генерирует видео)" } }];
}
if (!image_url && !product_video_id) {
  return [{ json: { ok: false, error: "image_url или product_video_id обязателен" } }];
}
if (image_url && !isHttp(image_url)) {
  return [{ json: { ok: false, error: "image_url должен быть http(s) URL (прямой URL изображения: PNG/JPG/WEBP)" } }];
}
let aspect_ratio = s(body.aspect_ratio) || '16x9';
if (['9x16', '16x9', '1x1'].indexOf(aspect_ratio) === -1) aspect_ratio = '16x9';
const language = s(body.language) || 'ru';
const target_audience = s(body.target_audience) || null;
const image_prompt = s(body.image_prompt) || null;
const video_prompt = s(body.video_prompt) || null;
const motion_style = s(body.motion_style) || null;
const webhook_url = s(body.webhook_url) || null;
const mode = image_url ? 'gen_image' : 'gen_video';
return [{ json: { ok: true, mode: mode, image_url: image_url || null, product_video_id: product_video_id || null, aspect_ratio: aspect_ratio, language: language, target_audience: target_audience, image_prompt: image_prompt, video_prompt: video_prompt, motion_style: motion_style, webhook_url: webhook_url } }];

// HTTP Request НЕ прокидывает входной item: $json здесь = ответ credits API.
// Валидацию берём кросс-нод-ссылкой на Code validate.
const v = $('Code validate').first().json;
if (v.ok === false) { return [{ json: v }]; }
const balance = Number($json.remaining_credits);
if (!Number.isFinite(balance)) { return [{ json: { ok: false, error: 'balance_unavailable', raw: $json } }]; }
if (balance < 20) { return [{ json: { ok: false, error: 'low_credits', balance: balance } }]; }
return [{ json: { ...v, ok: true, balance: balance } }];

const d = $json;
const p = { product_url: d.image_url, aspect_ratio: d.aspect_ratio || '16x9' };
if (d.image_prompt) p.image_prompt = d.image_prompt;
if (d.webhook_url) p.webhook_url = d.webhook_url;
return [{ json: { payload: p, meta: { target_audience: d.target_audience, language: d.language } } }];

const r = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const body = (r.body && typeof r.body === 'object' && !Array.isArray(r.body)) ? r.body : r;
const err = (typeof body.error === 'string' && body.error) ? body.error
  : (typeof body.detail === 'string' && body.detail) ? body.detail
  : (typeof body.message === 'string' && body.message) ? body.message : null;
if (!body.id || err) {
  return [{ json: { ok: false, error: err || 'invalid_response_no_id', raw: r } }];
}
return [{
  json: {
    ok: true,
    product_video_id: body.id || null,
    status: body.status || null,
    generated_photo_url: body.generated_photo_url || null,
    failed_reason: body.failed_reason || null,
    credits_used: body.credits_used || 0,
    raw: body
  }
}];

const d = $json;
const p = {};
if (d.motion_style) p.motion_style = d.motion_style;
if (d.video_prompt) p.video_prompt = d.video_prompt;
if (d.webhook_url) p.webhook_url = d.webhook_url;
const id = d.product_video_id;
return [{ json: { id: id, url: 'https://api.creatify.ai/api/product_to_videos/' + id + '/gen_video/', payload: p, meta: { target_audience: d.target_audience, language: d.language } } }];

const r = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const body = (r.body && typeof r.body === 'object' && !Array.isArray(r.body)) ? r.body : r;
const err = (typeof body.error === 'string' && body.error) ? body.error
  : (typeof body.detail === 'string' && body.detail) ? body.detail
  : (typeof body.message === 'string' && body.message) ? body.message : null;
if (!body.id || err) {
  return [{ json: { ok: false, error: err || 'invalid_response_no_id', raw: r } }];
}
return [{
  json: {
    ok: true,
    product_video_id: body.id || null,
    status: body.status || null,
    generated_photo_url: body.generated_photo_url || null,
    generated_video_url: body.generated_video_url || null,
    failed_reason: body.failed_reason || null,
    credits_used: body.credits_used || 0,
    raw: body
  }
}];
